  VALUES ('les-phases-de-la-rupture-chez-l-homme', '/blog/phases-rupture-homme.webp', 'mathieu-courtin', 'published', '2026-02-21T00:00:00.000Z')
  ON CONFLICT (internal_slug) DO UPDATE SET
