  -- Translation: de
  INSERT INTO public.blog_article_translations (article_id, lang, slug, title, meta_title, meta_description, featured_image_alt, excerpt, introduction, quick_summary, sections, is_complete)
  VALUES (
    art_id,
    'de',
    'trennungsphasen-beim-mann',
    'Die Phasen der Trennung beim Mann',
    'Die Phasen der Trennung beim Mann | 6 Stufen erklärt',
    'Entdecken Sie die 6 Phasen der Trennung beim Mann: von der Verleugnung bis zum Neuaufbau. Verstehen Sie jede Phase, um eine Trennung besser zu bewältigen.',
    'Mann, der die Phasen einer Trennung durchlebt',
    'Die 6 Phasen der Trennung beim Mann: von der Verleugnung bis zum Neuaufbau.',
    '<p>Man sagt oft, dass Männer weniger unter einer Trennung leiden. Dass sie schneller wieder auf die Beine kommen, dass sie ohne große Schäden weitermachen. Das stimmt nicht. Was aber stimmt, ist, dass sie es anders erleben — und oft erst später.</p>
<p>Während eine Frau den <strong>Trennungsschmerz</strong> in der Regel fast sofort spürt, lässt sich der Mann Zeit, ihn zuzulassen. Er kann ausgehen, lachen, Party um Party machen, den Anschein erwecken, dass alles gut ist… und drei Monate später zusammenbrechen, wenn er sich an einem Sonntagabend allein wiederfindet und die Realität ihn mit voller Wucht einholt.</p>
<p>Die <strong>Phasen der Trennung beim Mann</strong> zu verstehen, ist in vielerlei Hinsicht nützlich. Ob Sie ein Mann sind, der eine Trennung durchmacht und versucht, das Erlebte in Worte zu fassen, oder eine Frau, die verstehen möchte, wie ihr Ex die Dinge erlebt — dieser Artikel ist für Sie.</p>',
    '["Die Trennung beim Mann durchläuft 6 Phasen: Verleugnung, emotionale Betäubung, Wut, Bewusstwerdung, echte Trauer und Neuaufbau.","Diese Phasen verlaufen nicht linear und variieren je nach Person.","Männer drücken ihren Schmerz anders aus, oft verzögert.","Diese Phasen zu verstehen hilft, die Trennung besser zu bewältigen — oder den Ex besser zu verstehen."]'::jsonb,
    '[{"id":"phase-1-verleugnung","title":"Phase 1 — Die Verleugnung: „Es wird schon wieder, das ist nur vorübergehend\"","content":"<p>In den ersten Stunden und Tagen nach einer Trennung realisieren viele Männer nicht wirklich, was gerade passiert ist. Es gibt eine Art Schleier. Ein <strong>automatischer Schutzmechanismus</strong>, der verhindert, dass der Schmerz zu schnell eindringt.</p>\n<p>Konkret sieht das so aus: Der Mann funktioniert weiter normal, geht zur Arbeit, beantwortet Nachrichten, isst, schläft. Vielleicht denkt er, es sei nur ein Streit, dass es sich legen wird, dass sie zurückkommen wird. Oder er verharmlost es bewusst: „Es lief sowieso schon lange nicht mehr.\"</p>\n<p>Diese <strong>Verleugnung nach der Trennung</strong> ist keine Schwäche. Es ist eine biologische Reaktion. Das Gehirn schützt den Einzelnen vor einem zu brutalen emotionalen Schock, indem es die Verarbeitung der Information verzögert. Das Problem ist, dass das Aufschieben des Schmerzes ihn nur in die Zukunft verlagert.</p>","subsections":[]},{"id":"phase-2-betaeubung","title":"Phase 2 — Die Betäubung: sich ablenken, um nichts zu fühlen","content":"<p>Dann folgt eine Phase, die viele Männer gut kennen, ohne sie benennen zu können. Die <strong>emotionale Betäubung durch Aktion</strong>. Man stürzt sich in die Arbeit, den Sport, Unternehmungen, Feierabendbiere mit Freunden. Man „lebt sein Leben\", manchmal sogar besser als vorher, zumindest dem Anschein nach.</p>\n<p>Manche Männer haben eine Affäre nach der anderen. Nicht aus echtem Verlangen, sondern weil Verführung und die Aufmerksamkeit anderer als Pflaster dienen. Andere <strong>betäuben sich, um die Trennung zu vergessen</strong>, indem sie sich in Serien, Videospiele, Alkohol vertiefen. Alles, nur nicht allein mit seinen Gedanken sein.</p>\n<p>Diese Phase kann Wochen, manchmal Monate dauern. Sie wird gesellschaftlich geschätzt — man sagt, er „kommt gut klar\", er habe „Resilienz\". In Wirklichkeit läuft er vor sich selbst davon und die <strong>Liebestrauer wartet geduldig</strong> hinter der Tür.</p>\n<table><thead><tr><th>Was man von außen sieht</th><th>Was wirklich passiert</th></tr></thead><tbody><tr><td>Er geht viel aus, scheint gut drauf zu sein</td><td>Er betäubt sich, um nicht zu denken</td></tr><tr><td>Er hat ständig neue Bekanntschaften</td><td>Er versucht, eine Leere zu füllen</td></tr><tr><td>Er spricht kaum über seine Trennung</td><td>Er weiß noch nicht, wie er sie benennen soll</td></tr><tr><td>Er scheint „abgeschlossen\" zu haben</td><td>Die Trauer hat noch gar nicht begonnen</td></tr></tbody></table>","subsections":[]},{"id":"phase-3-wut","title":"Phase 3 — Die Wut: die erste Emotion, die hervorbricht","content":"<p>Wenn sich der Schleier der Verleugnung zu lüften beginnt, ist es nicht immer Traurigkeit, die zuerst kommt. Bei vielen Männern ist es die <strong>Wut nach der Trennung</strong>. Eine manchmal heftige Wut, gerichtet gegen die Ex, gegen die Situation, gegen sich selbst.</p>\n<p>Man wirft dem anderen vor, einen verlassen, betrogen, verändert zu haben. Man spielt Szenen im Kopf nach, findet alle Argumente, die man damals nicht ausgesprochen hat. Man schickt Nachrichten, die man am nächsten Tag bereut. Man spricht mit Freunden über sie — mit etwas zu viel Intensität — was übrigens oft das erste Zeichen ist, dass man noch nicht darüber hinweg ist.</p>\n<p><strong>Wut in der Liebestrauer</strong> ist eine normale, sogar gesunde Emotion. Sie gehört zu den Abwehrmechanismen des Ego. Problematisch wird es, wenn sie stagniert, wenn sie zum einzigen zugänglichen emotionalen Register wird — denn dann verhindert sie den Zugang zur Traurigkeit, die das wahre Tor zur Heilung ist.</p>","subsections":[]},{"id":"phase-4-bewusstwerdung","title":"Phase 4 — Die Bewusstwerdung: wenn es real wird","content":"<p>Oft ist es eine banale Situation, die diese Phase auslöst. Ein Ort, den man gemeinsam besucht hat. Ein Lied. Ein Gegenstand, der in einer Schublade gefunden wird. Und dann setzt sich die <strong>Realität der Trennung</strong> endlich durch, in ihrer ganzen Brutalität.</p>\n<p>Der Mann versteht, nicht nur intellektuell, sondern emotional, dass es vorbei ist. Dass sie nicht zurückkommen wird. Dass das Leben, das er sich gemeinsam vorgestellt hat, nicht stattfinden wird. Oft ist es in diesem Stadium, dass Fragen aufkommen: War es meine Schuld? Hätte ich es anders machen können? Habe ich die richtigen Entscheidungen getroffen?</p>\n<p>Diese <strong>Bewusstwerdung nach der Trennung</strong> ist wertvoll, vorausgesetzt, man verfällt nicht in Grübeln. Sich mit Klarheit zu hinterfragen ist etwas anderes als sich endlos zu geißeln. Das eine hilft zu wachsen, das andere hält einen fest.</p>\n<p>Es ist auch in dieser Phase, dass manche Männer versuchen, <strong>ihre Ex zu kontaktieren</strong> — um „Antworten zu bekommen\", um „richtig abzuschließen\". Das ist selten eine gute Idee. Die Antworten, die man sucht, kommen selten vom anderen: sie kommen von einem selbst, mit der Zeit.</p>","subsections":[]},{"id":"phase-5-echte-trauer","title":"Phase 5 — Die echte Trauer: die Traurigkeit, die man nicht hereingelassen hatte","content":"<p>Das ist die Phase, die viele Männer am längsten hinauszögern — und doch ist sie diejenige, die man durchleben muss, um wirklich zu heilen. Traurigkeit hereinzulassen bedeutet, Verletzlichkeit zu akzeptieren. Und für viele Männer, die seit der Kindheit darauf konditioniert wurden, nicht zu weinen, „stark zu sein\", ist das eine schwierige Übung.</p>\n<p>Die <strong>Liebestrauer beim Mann</strong> ähnelt Trauer im Allgemeinen. Es gibt Tage, an denen es besser geht, Tage, an denen alles wieder zusammenbricht. Morgen, die leichter erscheinen, und Nächte, die zu lang dauern. Es ist nicht linear, unvorhersehbar, und völlig normal.</p>\n<p>Hier ist, was Männer oft während dieser <strong>Traurigkeitsphase nach der Trennung</strong> erleben:</p>\n<ul>\n<li>Ungewöhnliche Müdigkeit, körperlich und mental</li>\n<li>Schlafstörungen (zu viel oder zu wenig)</li>\n<li>Interessenverlust an Dingen, die sie begeistert haben</li>\n<li>Ein Bedürfnis nach Einsamkeit, das mit einem intensiven Bedürfnis nach Gesellschaft abwechselt</li>\n<li>Wiederkehrende Gedanken über die Beziehung, über das, was hätte sein können</li>\n<li>Eine umfassendere Infragestellung ihrer Identität</li>\n</ul>\n<p>Diese Phase kann einige Wochen oder mehrere Monate dauern, je nach Dauer der Beziehung, Intensität der Gefühle und den emotionalen Ressourcen jedes Einzelnen. Es gibt keinen Zeitplan.</p>","subsections":[]},{"id":"phase-6-neuaufbau","title":"Phase 6 — Akzeptanz und Neuaufbau: sich selbst wiederfinden","content":"<p>Die letzte Phase ist keine Ziellinie. Es ist eher ein allmählicher Wandel — ein Morgen, an dem man merkt, dass man an etwas anderes gedacht hat, dass man wirklich gelacht hat, dass man nach vorne schaut, ohne dass die Vergangenheit zu stark zieht.</p>\n<p>Die <strong>Akzeptanz der Trennung</strong> bedeutet nicht „es tut nicht mehr weh\". Es bedeutet „ich kann damit leben\". Es ist eine Form von Frieden. Man leugnet nicht mehr, man flieht nicht mehr, man kämpft nicht mehr. Die Beziehung hat existiert, sie war wichtig, sie ist vorbei — und man kann sich jetzt an sie erinnern, ohne dass es ein Loch in der Brust hinterlässt.</p>\n<p>Der <strong>Neuaufbau nach einer Trennung</strong> führt oft über mehrere Wege:</p>\n<ul>\n<li><strong>Sich selbst wiederfinden</strong>, zunächst. Viele Männer stellen nach einer Trennung fest, dass sie unterwegs Teile von sich verloren haben — vernachlässigte Leidenschaften, beiseitegeschobene Freunde, aufgegebene Projekte. Diese Zeit ist die Gelegenheit, sie zurückzuholen.</li>\n<li><strong>Wieder allein sein lernen</strong>, dann. Nicht im Sinne einer erlittenen Einsamkeit, sondern einer gewählten. Zu wissen, dass man allein gut sein kann, ist eines der solidesten Fundamente für eine zukünftige <a href=\"https://quiz-couple.com/de/gesunde-beziehung-test\">gesunde Beziehung</a>.</li>\n<li><strong>Sich erlauben, die Zukunft ins Auge zu fassen</strong>. Nicht unbedingt sofort mit jemand anderem — sondern einfach, sich erlauben, wieder zu wollen.</li>\n</ul>","subsections":[]},{"id":"warum-anders","title":"Warum erleben Männer die Trennung anders?","content":"<p>Es liegt nicht in den Genen. Es ist größtenteils kulturell. <strong>Männer und Verletzlichkeit</strong> haben eine komplizierte Beziehung, aufgebaut auf Jahrzehnten sozialer Erwartungen: „sei stark\", „wein nicht\", „mach weiter\". Ergebnis: Viele Männer haben nicht die emotionalen Werkzeuge entwickelt, um eine <strong>Trennung effektiv zu bewältigen</strong>.</p>\n<p>Sie sind es oft nicht gewohnt, mit ihren Freunden über ihr Liebesleben zu sprechen. Sie haben nicht die gleichen Codes wie Frauen, um sich gegenseitig in solchen Momenten zu unterstützen. Sie verinnerlichen, dann explodieren sie — oder gehen leise aus.</p>\n<p>Die gute Nachricht? Diese Muster können sich ändern. Das <strong>emotionale Bewusstsein</strong> — diesen Artikel zu lesen ist bereits ein Teil davon — ermöglicht es, die Trauer anders zu durchleben. Mit etwas mehr Klarheit, etwas weniger Flucht.</p>","subsections":[]},{"id":"was-dieser-artikel-nicht-sagt","title":"Was dieser Artikel nicht sagt","content":"<p>Jede Trennung ist einzigartig. Jeder Mann ist einzigartig. Diese <strong>Trennungsphasen</strong> werden nicht unbedingt in dieser Reihenfolge erlebt, dauern nicht gleich lang, und manche können sich überschneiden oder wiederkehren. Diese Einteilung ist ein Verständniswerkzeug, keine Diagnose.</p>\n<p>Wenn Ihre Trennung von einer <strong>anhaltenden Depression</strong>, dunklen Gedanken oder einer Unfähigkeit begleitet wird, seit mehreren Wochen im Alltag zu funktionieren, bleiben Sie damit nicht allein. Um Hilfe zu bitten ist der mutigste Akt, den es gibt.</p>\n<p>Um weiterzugehen und Ihre Beziehung besser zu verstehen, können Sie <a href=\"https://quiz-couple.com/de/paar-kompatibilitaetstest\">Ihre Beziehung testen</a> oder überprüfen, ob Ihre Beziehung Anzeichen einer <a href=\"https://quiz-couple.com/de/toxische-beziehung-test\">toxischen Beziehung</a> zeigt.</p>","subsections":[]}]'::jsonb,
    true
  )
