  -- Translation: en
  INSERT INTO public.blog_article_translations (article_id, lang, slug, title, meta_title, meta_description, featured_image_alt, excerpt, introduction, quick_summary, sections, is_complete)
  VALUES (
    art_id,
    'en',
    'things-not-accept-relationship',
    'Things You Should Never Accept in a Relationship',
    'Things Not to Accept in a Relationship | Essential Boundaries',
    'Discover things you should never accept in a relationship: disrespect, manipulation, toxic jealousy. Learn to set healthy boundaries. Free complete guide.',
    'Couple setting boundaries in their romantic relationship',
    'Behaviors you should never tolerate in a relationship and how to set limits.',
    '<p>There are things we accept in a relationship without really noticing. Not all at once — gradually. A <strong>hurtful remark</strong>, once. Then twice. Then it becomes the norm. A <strong>disrespectful behavior</strong> that shocks at first, and that we end up finding "normal" because we''ve gotten used to it. This is called the <strong>normalization of toxic behaviors</strong>, and it''s one of the most insidious mechanisms in a relationship that''s going off the rails.</p>
<p>Talking about <strong>things not to accept in a relationship</strong> isn''t about building a case against imperfect relationships. Every relationship has its friction, its clumsiness, its tough moments. It would be dishonest to say otherwise. But there''s a real difference between an <strong>imperfect relationship</strong> and a <strong>relationship that hurts you</strong>. Between a partner who makes mistakes and a partner who doesn''t respect you.</p>
<p>This article is here to help you make that distinction. No drama, no judgment — but no complacency either. And if you''re unsure about the health of your relationship, you can start by taking our <a href="https://quiz-couple.com/en/toxic-relationship-test">toxic relationship test</a> — it''s free and confidential.</p>',
    '["Disrespect, in all its forms, is the first thing you should never tolerate.","Humiliations disguised as jokes are a form of emotional abuse.","Excessive jealousy and control are never proof of love.","Setting boundaries is not an act of hostility — it''s self-respect.","A healthy relationship requires both partners to be able to say no."]'::jsonb,
    '[{"id":"lack-of-respect","title":"Lack of respect, in all its forms","content":"<p><strong>Respect in a relationship</strong> is the foundation. Before love, before intimacy, before everything else. A <strong>relationship without respect</strong> isn''t a relationship — it''s a toxic cohabitation that wears down both people, even if one of them doesn''t realize it.</p>\n<p><strong>Disrespect in a relationship</strong> isn''t limited to insults. It takes dozens of forms, often less visible: consistently interrupting, <strong>minimizing emotions</strong> (\"you''re overreacting again\"), mocking in front of friends or family, ignoring repeated requests. These behaviors, taken individually, may seem harmless. Accumulated, they build a <strong>dynamic that destroys self-esteem</strong>.</p>\n<p>Not tolerating disrespect doesn''t mean being oversensitive. It simply means acknowledging that you have value, and that this <strong>value doesn''t disappear</strong> once you''re in a relationship. To better understand your couple dynamic, our <a href=\"https://quiz-couple.com/en/couple-compatibility-test\">couple compatibility test</a> can help you see things more clearly.</p>","subsections":[]},{"id":"humiliations-as-jokes","title":"Humiliations, even \"as a joke\"","content":"<p>This is one of the <strong>easiest behaviors to minimize</strong> and one of the most devastating. <strong>Mockery dressed up as humor</strong> — about your appearance, your intelligence, your skills, your choices — causes real damage, even when delivered with a smile.</p>\n<p>\"It was a joke, you have no sense of humor.\" You may have heard this little phrase before. It serves to <strong>invalidate your feelings</strong> while continuing the hurtful behavior. It''s doubly toxic: you''re hurt, then you''re made to bear the <strong>responsibility for being hurt</strong>.</p>\n<p>A joke between partners can be tender, funny, a true <strong>language of intimacy</strong>. But a joke that makes you uncomfortable, that you didn''t ask for, that touches something sensitive for you — that''s no longer a joke. It''s a <strong>humiliation wrapped in packaging</strong>.</p>","subsections":[]},{"id":"toxic-jealousy-control","title":"Toxic jealousy and control","content":"<p><strong>Jealousy in a relationship</strong>, in its mild form, can be a sign that you care about each other. But when it becomes systematic, overwhelming, constraining — it changes nature. <strong>Excessive jealousy</strong> and control are not proof of love. They are <strong>forms of domination</strong>.</p>\n<p>Checking phones, questioning every outing, demanding to know who you''re with at all times, resenting your <strong>friendships or professional relationships</strong>, criticizing the way you dress — these behaviors have nothing to do with love. They have to do with the <strong>need for control</strong> and insecurity, which become a prison for the other person.</p>\n<p>What makes this situation particularly difficult to handle is that the jealous partner often presents this behavior as <strong>proof of attachment</strong>. \"I do this because I love you too much.\" No. Love doesn''t take away freedom. Love doesn''t imprison. Our <a href=\"https://quiz-couple.com/en/toxic-relationship-test\">toxic relationship test</a> can help you evaluate whether this jealousy crosses healthy boundaries.</p>","subsections":[]},{"id":"emotional-manipulation","title":"Emotional manipulation","content":"<p><strong>Emotional manipulation in a relationship</strong> is one of the hardest forms of abuse to identify, precisely because it leaves no visible trace. <strong>Recognizing manipulation</strong> often requires perspective — and that''s exactly what the manipulator seeks to take away from you.</p>\n<p>Here are some behaviors that constitute <strong>manipulation in a relationship</strong>:</p>\n<ul>\n<li><strong>Gaslighting</strong>: making you doubt your own perception of reality (\"that''s not what happened,\" \"you''re making things up\")</li>\n<li><strong>Emotional blackmail</strong>: threatening to leave, to harm themselves, to cut ties if you don''t do what''s expected of you</li>\n<li><strong>Chronic guilt-tripping</strong>: making you bear responsibility for all the couple''s problems</li>\n<li><strong>Punitive silence</strong>: deliberately ignoring you to make you suffer and make you give in</li>\n<li><strong>Hot/cold blowing</strong>: alternating between tenderness and distance to create emotional dependency</li>\n</ul>\n<p>These behaviors have one thing in common: they put you in a <strong>permanently weak position</strong>, where you walk on eggshells, where you constantly seek the other person''s approval. This is not love. This is <strong>psychological control</strong>.</p>","subsections":[]},{"id":"chronic-indifference","title":"Chronic indifference","content":"<p>We talk a lot about violence, manipulation, jealousy. But there''s another form of <strong>relationship distress</strong>, less dramatic and equally destructive: <strong>indifference that settles in permanently</strong>.</p>\n<p>A partner who no longer takes interest in what you''re going through, who no longer asks questions, who no longer notices your efforts, who is <strong>physically present but emotionally absent</strong> — that causes deep damage. Not as visible as conflict, but just as real.</p>\n<p><strong>Chronic indifference in a relationship</strong> eventually makes you doubt your own worth. You start wondering if you''re interesting enough, lovable enough, good enough. You try to <strong>exist in the other person''s eyes</strong> and find nothing there anymore. This feeling of invisibility is exhausting, and it shouldn''t be your daily reality.</p>\n<p>Of course, all couples go through <strong>phases of routine</strong>, distance, fatigue. That''s human. What''s problematic is when indifference becomes the norm and the other person makes <strong>no effort to change</strong>, even when you talk about it. If you''re going through such a phase, our <a href=\"https://quiz-couple.com/en/healthy-relationship-test\">healthy relationship test</a> can help you gain perspective.</p>","subsections":[]},{"id":"violence","title":"Violence — verbal, psychological, physical","content":"<p>Let''s be clear, without beating around the bush: <strong>no form of violence is acceptable</strong> in a relationship. Not <strong>physical violence</strong>, not <strong>verbal violence</strong>, not <strong>psychological violence</strong>. None.</p>\n<p>And yet, millions of people live in relationships where they are regularly insulted, belittled, threatened — and end up believing it''s normal, or even deserved. This is the result of <strong>progressive conditioning</strong>, and that''s precisely why these situations are so hard to leave.</p>\n<p><strong>Domestic violence</strong> doesn''t happen overnight. It sets in gradually: a first time that gets minimized, an excuse that gets accepted, a <strong>behavior that gets normalized</strong>. Until it becomes hard to remember what \"normal\" means.</p>\n<p>If you''re living in a violent situation, regardless of its form, regardless of whether you still love that person — <strong>you deserve to be safe</strong>. Seeking help isn''t betraying your partner. It''s protecting yourself.</p>","subsections":[]},{"id":"contempt-devaluation","title":"Contempt and repeated devaluation","content":"<p>There''s a difference between criticizing and showing contempt. Criticism, even when hard to hear, can be constructive. <strong>Contempt in a relationship</strong>, however, serves no purpose. Contempt and <strong>repeated devaluation</strong> attack the other person''s identity directly, their worth as a human being.</p>\n<p>Exasperated sighs, <strong>condescending looks</strong>, remarks implying you''re incompetent or unintelligent, <strong>unfavorable comparisons</strong> with others — these behaviors, identified by researcher John Gottman as one of the \"Four Horsemen of the Apocalypse\" in a relationship, are among the most <strong>predictive of a future breakup</strong>.</p>\n<p>But before leading to breakup, they lead to something even more serious: the <strong>destruction of self-esteem</strong>. Being treated with contempt by someone you love is a wound that doesn''t heal easily.</p>","subsections":[]},{"id":"summary-table","title":"Summary table: accept or not accept?","content":"<table><thead><tr><th>Behavior</th><th>Worth putting in perspective if…</th><th>Not acceptable if…</th></tr></thead><tbody>\n<tr><td><strong>A hurtful remark</strong></td><td>It''s rare and followed by sincere apologies</td><td>It''s repeated and minimized</td></tr>\n<tr><td><strong>Jealousy</strong></td><td>It''s mild and not constraining</td><td>It limits your freedom</td></tr>\n<tr><td><strong>A violent conflict</strong></td><td>It''s exceptional and worked through together</td><td>It happens regularly</td></tr>\n<tr><td><strong>Emotional distance</strong></td><td>It''s a phase linked to stress</td><td>It''s the permanent state of the relationship</td></tr>\n<tr><td><strong>Criticism</strong></td><td>It''s constructive and well-intentioned</td><td>It aims to diminish you</td></tr>\n</tbody></table>","subsections":[]},{"id":"why-we-accept","title":"Why we accept despite everything — and how to get out","content":"<p>Knowing you shouldn''t accept something isn''t always enough to change things. The <strong>fear of loneliness</strong>, the sincere love you have for the other person, the difficulty imagining your life differently, the <strong>shame of others'' judgment</strong> — all these factors keep people in <strong>relationships that hurt them</strong>.</p>\n<p>There''s no judgment for someone who stays in a difficult situation. These <strong>psychological mechanisms</strong> are powerful, often unconscious. But there''s one important thing to understand: <strong>setting boundaries is possible</strong>. And setting them doesn''t necessarily mean leaving the relationship.</p>\n<p>Clearly communicating what you no longer accept, saying \"this behavior hurts me and I can''t keep enduring it,\" is an <strong>act of self-respect</strong> — and sometimes, it''s the only way to give the relationship a real chance to change.</p>\n<p>If the person in front of you doesn''t listen, minimizes, does it again — then the question is no longer \"do I still love them?\" but \"<strong>do I respect myself enough</strong>\" to do things differently. You can use our <a href=\"https://quiz-couple.com/en/solve-couple-problem\">couple problem solver</a> to put words to your situation.</p>","subsections":[]},{"id":"setting-boundaries","title":"What setting boundaries says about you","content":"<p><strong>Setting boundaries in a relationship</strong> is not an act of hostility. It''s not being \"difficult,\" \"demanding,\" or \"hard to live with.\" It simply means knowing your worth and <strong>refusing to erase yourself</strong> to please someone else.</p>\n<p>The <strong>strongest relationships</strong> are those where both partners can say no, can express their discomforts, know that love doesn''t justify everything. Because <strong>true love</strong> — the kind that lasts, the kind that builds — doesn''t need you to disappear to exist.</p>\n<p>You have the right to demand respect, consideration, honesty. You have the right to feel <strong>emotionally safe</strong> in your relationship. And if you have any doubt, our <a href=\"https://quiz-couple.com/en/couple-compatibility-test\">couple compatibility test</a> is a good starting point to take stock.</p>","subsections":[]}]'::jsonb,
    true
  )
