  -- Translation: de
  INSERT INTO public.blog_article_translations (article_id, lang, slug, title, meta_title, meta_description, featured_image_alt, excerpt, introduction, quick_summary, sections, is_complete)
  VALUES (
    art_id,
    'de',
    'grenzen-beziehung-nicht-akzeptieren',
    'Was man in einer Beziehung niemals akzeptieren sollte',
    'Grenzen in der Beziehung | Was nicht akzeptabel ist',
    'Erfahren Sie, was in einer Beziehung nicht akzeptabel ist: Respektlosigkeit, Manipulation, toxische Eifersucht. Lernen Sie Grenzen zu setzen. Kostenloser Leitfaden.',
    'Paar setzt Grenzen in ihrer Liebesbeziehung',
    'Verhaltensweisen, die in einer Beziehung nicht toleriert werden sollten.',
    '<p>Es gibt Dinge, die wir in einer Beziehung akzeptieren, ohne es wirklich zu bemerken. Nicht auf einmal — schrittweise. Eine <strong>verletzende Bemerkung</strong>, einmal. Dann zweimal. Dann wird es zur Norm. Ein <strong>respektloses Verhalten</strong>, das anfangs schockiert und das wir irgendwann "normal" finden, weil wir uns daran gewöhnt haben. Das nennt man die <strong>Normalisierung toxischer Verhaltensweisen</strong> — einer der heimtückischsten Mechanismen in einer Beziehung, die aus dem Ruder läuft.</p>
<p>Über <strong>Dinge zu sprechen, die man in einer Beziehung nicht akzeptieren sollte</strong>, bedeutet nicht, unvollkommene Beziehungen anzuklagen. Jede Beziehung hat ihre Reibungen, ihre Ungeschicklichkeiten, ihre schwierigen Momente. Aber es gibt einen echten Unterschied zwischen einer <strong>unvollkommenen Beziehung</strong> und einer <strong>Beziehung, die Ihnen schadet</strong>.</p>
<p>Dieser Artikel hilft Ihnen, diese Unterscheidung zu treffen. Ohne Drama, ohne Verurteilung — aber auch ohne Nachsicht. Und wenn Sie unsicher sind, können Sie zunächst unseren <a href="https://quiz-couple.com/de/toxische-beziehung-test">Test für toxische Beziehungen</a> machen — kostenlos und vertraulich.</p>',
    '["Respektlosigkeit in all ihren Formen ist das Erste, was nicht toleriert werden sollte.","Als Scherz getarnte Demütigungen sind eine Form emotionalen Missbrauchs.","Übermäßige Eifersucht und Kontrolle sind niemals Liebesbeweise.","Grenzen zu setzen ist kein feindseliger Akt — es ist Selbstachtung.","Eine gesunde Beziehung erfordert, dass beide Partner Nein sagen können."]'::jsonb,
    '[{"id":"respektlosigkeit","title":"Respektlosigkeit in all ihren Formen","content":"<p><strong>Respekt in der Beziehung</strong> ist das Fundament. Vor der Liebe, vor der Vertrautheit, vor allem anderen. Eine <strong>Beziehung ohne Respekt</strong> ist keine Beziehung — es ist ein toxisches Zusammenleben, das beide Menschen zermürbt.</p>\n<p><strong>Respektlosigkeit in der Beziehung</strong> beschränkt sich nicht auf Beleidigungen. Sie nimmt dutzende Formen an: ständiges Unterbrechen, <strong>Emotionen herunterspielen</strong> (\"du übertreibst wieder\"), vor Freunden oder Familie verspotten, wiederholte Bitten ignorieren. Diese Verhaltensweisen, einzeln betrachtet, mögen harmlos erscheinen. Zusammen bauen sie eine <strong>Dynamik auf, die das Selbstwertgefühl zerstört</strong>.</p>\n<p>Respektlosigkeit nicht zu tolerieren bedeutet nicht, empfindlich zu sein. Es bedeutet einfach, sich daran zu erinnern, dass Sie einen Wert haben. Unser <a href=\"https://quiz-couple.com/de/paar-kompatibilitaetstest\">Paar-Kompatibilitätstest</a> kann Ihnen helfen, klarer zu sehen.</p>","subsections":[]},{"id":"demuetigung-als-scherz","title":"Demütigungen, auch „im Spaß\"","content":"<p>Dies ist eines der <strong>am leichtesten herunterzuspielenden Verhaltensweisen</strong> und eines der verheerendsten. <strong>Als Humor getarnte Spöttereien</strong> — über Ihr Aussehen, Ihre Intelligenz, Ihre Fähigkeiten, Ihre Entscheidungen — richten echten Schaden an, selbst wenn sie mit einem Lächeln vorgetragen werden.</p>\n<p>\"War doch nur ein Witz, du hast keinen Humor.\" Diesen kleinen Satz haben Sie vielleicht schon gehört. Er dient dazu, <strong>Ihre Gefühle zu entwerten</strong> und gleichzeitig das verletzende Verhalten fortzusetzen. Das ist doppelt toxisch: Man verletzt Sie und macht Sie dann für die <strong>Verantwortung, verletzt zu sein</strong>, verantwortlich.</p>\n<p>Ein Witz zwischen Partnern kann zärtlich sein, lustig, eine echte <strong>Sprache der Intimität</strong>. Aber ein Witz, der Ihnen unangenehm ist, den Sie nicht gewollt haben, der etwas Sensibles bei Ihnen berührt — das ist kein Witz mehr. Das ist eine <strong>Demütigung in Verpackung</strong>.</p>","subsections":[]},{"id":"toxische-eifersucht-kontrolle","title":"Toxische Eifersucht und Kontrolle","content":"<p><strong>Eifersucht in der Beziehung</strong> kann in ihrer leichten Form ein Zeichen dafür sein, dass man einander wichtig ist. Aber wenn sie systematisch, aufdringlich, einengend wird — ändert sie ihre Natur. <strong>Übermäßige Eifersucht</strong> und Kontrolle sind keine Liebesbeweise. Sie sind <strong>Formen der Dominanz</strong>.</p>\n<p>Das Handy kontrollieren, jeden Ausgang hinterfragen, ständig wissen wollen, mit wem Sie zusammen sind, Ihre <strong>Freundschaften oder beruflichen Beziehungen</strong> schlecht ertragen, Ihnen vorwerfen, wie Sie sich kleiden — diese Verhaltensweisen haben nichts mit Liebe zu tun. Sie haben mit <strong>Kontrollbedürfnis</strong> und Unsicherheit zu tun.</p>\n<p>Was diese Situation besonders schwierig macht: Der eifersüchtige Partner stellt dieses Verhalten oft als <strong>Beweis der Zuneigung</strong> dar. \"Ich mache das, weil ich dich so sehr liebe.\" Nein. Liebe nimmt keine Freiheit. Unser <a href=\"https://quiz-couple.com/de/toxische-beziehung-test\">Test für toxische Beziehungen</a> kann helfen, einzuschätzen, ob diese Eifersucht gesunde Grenzen überschreitet.</p>","subsections":[]},{"id":"emotionale-manipulation","title":"Emotionale Manipulation","content":"<p><strong>Emotionale Manipulation in der Beziehung</strong> ist eine der am schwersten zu erkennenden Formen von Missbrauch, gerade weil sie keine sichtbaren Spuren hinterlässt. <strong>Manipulation zu erkennen</strong> erfordert Abstand — und genau das versucht der Manipulator Ihnen zu nehmen.</p>\n<p>Einige Verhaltensweisen, die <strong>Manipulation in der Beziehung</strong> darstellen:</p>\n<ul>\n<li><strong>Gaslighting</strong>: Sie an Ihrer eigenen Wahrnehmung zweifeln lassen (\"das ist nicht passiert\", \"du erfindest Dinge\")</li>\n<li><strong>Emotionale Erpressung</strong>: drohen zu gehen, sich selbst zu verletzen, den Kontakt abzubrechen</li>\n<li><strong>Chronische Schuldzuweisung</strong>: Ihnen die Verantwortung für alle Probleme des Paares aufbürden</li>\n<li><strong>Bestrafendes Schweigen</strong>: Sie absichtlich ignorieren, um Sie leiden zu lassen</li>\n<li><strong>Heiß-Kalt-Behandlung</strong>: zwischen Zärtlichkeit und Distanz wechseln, um emotionale Abhängigkeit zu erzeugen</li>\n</ul>\n<p>Diese Verhaltensweisen haben eines gemeinsam: Sie bringen Sie in eine <strong>permanente Schwächeposition</strong>. Das ist keine Liebe. Das ist <strong>psychologische Kontrolle</strong>.</p>","subsections":[]},{"id":"chronische-gleichgueltigkeit","title":"Chronische Gleichgültigkeit","content":"<p>Man spricht viel über Gewalt, Manipulation, Eifersucht. Aber es gibt eine weitere Form von <strong>Beziehungsleid</strong>, weniger spektakulär und ebenso zerstörerisch: die <strong>Gleichgültigkeit, die sich dauerhaft einnistet</strong>.</p>\n<p>Ein Partner, der sich nicht mehr für Ihr Leben interessiert, keine Fragen mehr stellt, Ihre Bemühungen nicht mehr bemerkt, der <strong>physisch anwesend, aber emotional abwesend</strong> ist — das richtet tiefe Schäden an.</p>\n<p><strong>Chronische Gleichgültigkeit in der Beziehung</strong> lässt Sie an Ihrem eigenen Wert zweifeln. Man beginnt sich zu fragen, ob man interessant genug, liebenswert genug ist. Man versucht, <strong>im Blick des anderen zu existieren</strong> und findet dort nichts mehr.</p>\n<p>Natürlich durchlaufen alle Paare <strong>Phasen der Routine</strong>. Problematisch wird es, wenn Gleichgültigkeit zur Norm wird und der andere <strong>keine Anstalten macht, etwas zu ändern</strong>. Unser <a href=\"https://quiz-couple.com/de/test-gesunde-beziehung\">Test für gesunde Beziehungen</a> kann Ihnen helfen, Perspektive zu gewinnen.</p>","subsections":[]},{"id":"gewalt","title":"Gewalt — verbal, psychisch, physisch","content":"<p>Lassen Sie es uns klar sagen: <strong>Keine Form von Gewalt ist in einer Beziehung akzeptabel</strong>. Weder <strong>physische Gewalt</strong>, noch <strong>verbale Gewalt</strong>, noch <strong>psychische Gewalt</strong>. Keine.</p>\n<p>Und dennoch leben Millionen von Menschen in Beziehungen, in denen sie regelmäßig beleidigt, herabgesetzt, bedroht werden — und am Ende glauben, das sei normal. Das ist das Ergebnis einer <strong>schrittweisen Konditionierung</strong>.</p>\n<p><strong>Häusliche Gewalt</strong> geschieht nicht über Nacht. Sie schleicht sich stufenweise ein: ein erstes Mal, das heruntergespielt wird, eine Entschuldigung, die akzeptiert wird, ein <strong>Verhalten, das normalisiert wird</strong>.</p>\n<p>Wenn Sie in einer Gewaltsituation leben — <strong>Sie haben das Recht auf Sicherheit</strong>. Hilfe zu suchen ist kein Verrat. Es ist Selbstschutz.</p>","subsections":[]},{"id":"verachtung-abwertung","title":"Verachtung und wiederholte Abwertung","content":"<p>Es gibt einen Unterschied zwischen Kritisieren und Verachten. Kritik kann konstruktiv sein. <strong>Verachtung in der Beziehung</strong> hingegen hat keinen Nutzen. Verachtung und <strong>wiederholte Abwertung</strong> greifen die Identität des anderen direkt an.</p>\n<p>Genervte Seufzer, <strong>herablassende Blicke</strong>, Bemerkungen, die andeuten, dass Sie inkompetent oder unintelligent sind, <strong>nachteilige Vergleiche</strong> mit anderen — diese Verhaltensweisen, vom Forscher John Gottman als einer der \"Vier Reiter der Apokalypse\" identifiziert, gehören zu den <strong>stärksten Prädiktoren für eine Trennung</strong>.</p>\n<p>Aber bevor sie zur Trennung führen, führen sie zu etwas noch Gravierenderem: der <strong>Zerstörung des Selbstwertgefühls</strong>.</p>","subsections":[]},{"id":"uebersichtstabelle","title":"Übersichtstabelle: Akzeptieren oder nicht?","content":"<table><thead><tr><th>Verhalten</th><th>Relativieren, wenn…</th><th>Nicht akzeptieren, wenn…</th></tr></thead><tbody>\n<tr><td><strong>Eine verletzende Bemerkung</strong></td><td>Sie selten ist und aufrichtige Entschuldigung folgt</td><td>Sie wiederholt wird und heruntergespielt</td></tr>\n<tr><td><strong>Eifersucht</strong></td><td>Sie leicht ist und nicht einschränkend</td><td>Sie Ihre Freiheit begrenzt</td></tr>\n<tr><td><strong>Ein heftiger Konflikt</strong></td><td>Er eine Ausnahme ist und gemeinsam aufgearbeitet wird</td><td>Er regelmäßig vorkommt</td></tr>\n<tr><td><strong>Emotionale Distanz</strong></td><td>Sie eine stressbedingte Phase ist</td><td>Sie der Dauerzustand der Beziehung ist</td></tr>\n<tr><td><strong>Kritik</strong></td><td>Sie konstruktiv und wohlwollend ist</td><td>Sie darauf abzielt, Sie kleinzumachen</td></tr>\n</tbody></table>","subsections":[]},{"id":"warum-wir-akzeptieren","title":"Warum wir trotzdem akzeptieren — und wie man herauskommt","content":"<p>Zu wissen, dass man etwas nicht akzeptieren sollte, reicht nicht immer, um etwas zu ändern. Die <strong>Angst vor dem Alleinsein</strong>, die aufrichtige Liebe, die Schwierigkeit, sich ein anderes Leben vorzustellen, die <strong>Scham vor dem Urteil anderer</strong> — all diese Faktoren halten Menschen in <strong>Beziehungen, die ihnen schaden</strong>.</p>\n<p>Es gibt kein Urteil über jemanden, der in einer schwierigen Situation bleibt. Diese <strong>psychologischen Mechanismen</strong> sind mächtig. Aber es gibt etwas Wichtiges zu verstehen: <strong>Grenzen zu setzen ist möglich</strong>.</p>\n<p>Klar kommunizieren, was man nicht mehr akzeptiert, sagen \"dieses Verhalten verletzt mich und ich kann es nicht weiter ertragen\", ist ein <strong>Akt der Selbstachtung</strong>.</p>\n<p>Wenn die Person gegenüber nicht zuhört, herunterspielt, weitermacht — dann ist die Frage nicht mehr \"liebe ich sie noch?\" sondern \"<strong>respektiere ich mich genug</strong>\", um es anders zu machen. Unser <a href=\"https://quiz-couple.com/de/paar-problem-loesen\">Paar-Problemlöser</a> kann Ihnen helfen, Ihre Situation in Worte zu fassen.</p>","subsections":[]},{"id":"grenzen-setzen","title":"Was Grenzen setzen über Sie aussagt","content":"<p><strong>Grenzen in einer Beziehung zu setzen</strong> ist kein feindseliger Akt. Es ist nicht \"kompliziert\", \"anspruchsvoll\" oder \"schwierig\" zu sein. Es bedeutet einfach, seinen Wert zu kennen und sich <strong>nicht selbst zu vergessen</strong>, um jemand anderem zu gefallen.</p>\n<p>Die <strong>stärksten Beziehungen</strong> sind die, in denen beide Partner Nein sagen können, ihre Unbehagen ausdrücken können, wissen, dass Liebe nicht alles rechtfertigt. Denn <strong>wahre Liebe</strong> braucht nicht, dass Sie verschwinden, um zu existieren.</p>\n<p>Sie haben das Recht auf Respekt, Rücksicht, Ehrlichkeit. Sie haben das Recht, sich in Ihrer Beziehung <strong>emotional sicher</strong> zu fühlen. Unser <a href=\"https://quiz-couple.com/de/paar-kompatibilitaetstest\">Paar-Kompatibilitätstest</a> ist ein guter Ausgangspunkt.</p>","subsections":[]}]'::jsonb,
    true
  )
  ON CONFLICT (article_id, lang) DO UPDATE SET
    slug = EXCLUDED.slug,
    title = EXCLUDED.title,
    meta_title = EXCLUDED.meta_title,
