  -- Translation: it
  INSERT INTO public.blog_article_translations (article_id, lang, slug, title, meta_title, meta_description, featured_image_alt, excerpt, introduction, quick_summary, sections, is_complete)
  VALUES (
    art_id,
    'it',
    'cose-non-accettare-coppia',
    'Cose da non accettare mai in una relazione di coppia',
    'Cose da non accettare in coppia | Limiti essenziali',
    'Scopri le cose da non accettare in coppia: mancanza di rispetto, manipolazione, gelosia tossica. Impara a porre i tuoi limiti. Guida completa e gratuita.',
    'Coppia che stabilisce limiti nella propria relazione sentimentale',
    'I comportamenti da non tollerare mai in coppia e come porre i propri limiti.',
    '<p>Ci sono cose che accettiamo in coppia senza rendercene conto. Non tutto d''un colpo — progressivamente. Un <strong>commento che ferisce</strong>, una volta. Poi due. Poi diventa la norma. Un <strong>comportamento irrispettoso</strong> che all''inizio sciocca, e che finiamo per trovare "normale" perché ci siamo abituati. Si chiama <strong>normalizzazione dei comportamenti tossici</strong>, ed è uno dei meccanismi più insidiosi in una relazione che deraglia.</p>
<p>Parlare delle <strong>cose da non accettare in coppia</strong> non è fare un atto d''accusa contro le relazioni imperfette. Ogni relazione ha le sue frizioni, le sue goffaggini, i suoi momenti difficili. Ma c''è una vera differenza tra una <strong>relazione imperfetta</strong> e una <strong>relazione che ti fa del male</strong>. Tra un partner che commette errori e un partner che non ti rispetta.</p>
<p>Questo articolo è qui per aiutarti a fare questa distinzione. Senza drammi, senza giudizio — ma senza compiacenza. E se hai dubbi sulla salute della tua relazione, puoi iniziare con il nostro <a href="https://quiz-couple.com/it/test-relazione-tossica">test di relazione tossica</a> — gratuito e confidenziale.</p>',
    '["La mancanza di rispetto, in tutte le sue forme, è la prima cosa da non tollerare.","Le umiliazioni mascherate da battute sono una forma di maltrattamento.","La gelosia eccessiva e il controllo non sono mai prove d''amore.","Porre dei limiti non è un atto di ostilità — è rispetto per sé stessi.","Una relazione sana richiede che entrambi i partner sappiano dire di no."]'::jsonb,
    '[{"id":"mancanza-di-rispetto","title":"La mancanza di rispetto, in tutte le sue forme","content":"<p>Il <strong>rispetto in coppia</strong> è la base. Prima dell''amore, prima della complicità, prima di tutto. Una <strong>relazione senza rispetto</strong> non è una relazione — è una convivenza tossica che logora entrambe le persone.</p>\n<p>La <strong>mancanza di rispetto nella coppia</strong> non si limita agli insulti. Assume decine di forme: interrompere sistematicamente, <strong>minimizzare le emozioni</strong> dell''altro (\"stai esagerando di nuovo\"), prendere in giro davanti ad amici o familiari, ignorare le richieste ripetute. Questi comportamenti, presi singolarmente, possono sembrare insignificanti. Accumulati, costruiscono una <strong>dinamica che distrugge l''autostima</strong>.</p>\n<p>Non tollerare la mancanza di rispetto non significa essere suscettibili. Significa semplicemente ricordare che avete un valore. Il nostro <a href=\"https://quiz-couple.com/it/test-compatibilita-coppia\">test di compatibilità di coppia</a> può aiutarvi a vederci più chiaro.</p>","subsections":[]},{"id":"umiliazioni-per-scherzo","title":"Le umiliazioni, anche \"per scherzo\"","content":"<p>È uno dei <strong>comportamenti più facili da minimizzare</strong> e dei più devastanti. Le <strong>prese in giro mascherate da umorismo</strong> — sul vostro aspetto, la vostra intelligenza, le vostre capacità — causano danni reali, anche quando sono formulate con un sorriso.</p>\n<p>\"Era una battuta, non hai senso dell''umorismo.\" Questa frasetta l''avete forse già sentita. Serve a <strong>invalidare le vostre emozioni</strong> continuando il comportamento offensivo. È doppiamente tossico: vi feriscono, poi vi fanno portare la <strong>responsabilità di essere stati feriti</strong>.</p>\n<p>Una battuta tra partner può essere tenera, divertente, un vero <strong>linguaggio di intimità</strong>. Ma una battuta che vi mette a disagio, che non avete chiesto, che tocca qualcosa di sensibile per voi — quella non è più una battuta. È un''<strong>umiliazione confezionata</strong>.</p>","subsections":[]},{"id":"gelosia-tossica-controllo","title":"La gelosia tossica e il controllo","content":"<p>La <strong>gelosia nella coppia</strong>, nella sua forma leggera, può essere segno che ci si tiene all''altro. Ma quando diventa sistematica, invadente, limitante — cambia natura. La <strong>gelosia eccessiva</strong> e il controllo non sono prove d''amore. Sono <strong>forme di dominio</strong>.</p>\n<p>Controllare il telefono, interrogare su ogni uscita, pretendere di sapere con chi siete in ogni momento, mal sopportare le vostre <strong>relazioni amicali o professionali</strong>, rimproverarvi il modo di vestire — questi comportamenti non hanno nulla a che fare con l''amore. Hanno a che fare con il <strong>bisogno di controllo</strong> e l''insicurezza.</p>\n<p>Ciò che rende questa situazione particolarmente difficile è che il partner geloso presenta spesso questo comportamento come una <strong>prova di attaccamento</strong>. \"Lo faccio perché ti amo troppo.\" No. L''amore non toglie la libertà. Il nostro <a href=\"https://quiz-couple.com/it/test-relazione-tossica\">test di relazione tossica</a> può aiutarvi a valutare se questa gelosia supera i limiti del sano.</p>","subsections":[]},{"id":"manipolazione-emotiva","title":"La manipolazione emotiva","content":"<p>La <strong>manipolazione emotiva nella coppia</strong> è una delle forme di maltrattamento più difficili da identificare, proprio perché non lascia tracce visibili. <strong>Riconoscere la manipolazione</strong> richiede distacco — ed è esattamente ciò che il manipolatore cerca di togliervi.</p>\n<p>Alcuni comportamenti che costituiscono <strong>manipolazione nella coppia</strong>:</p>\n<ul>\n<li><strong>Gaslighting</strong>: farvi dubitare della vostra percezione della realtà (\"non è successo\", \"ti stai inventando tutto\")</li>\n<li><strong>Ricatto emotivo</strong>: minacciare di andarsene, di farsi del male, di tagliare i ponti</li>\n<li><strong>Colpevolizzazione cronica</strong>: farvi portare la responsabilità di tutti i problemi della coppia</li>\n<li><strong>Silenzio punitivo</strong>: ignorarvi deliberatamente per farvi soffrire</li>\n<li><strong>Caldo/freddo</strong>: alternare tenerezza e distanza per creare dipendenza emotiva</li>\n</ul>\n<p>Questi comportamenti hanno un punto in comune: vi mettono in una <strong>posizione di debolezza permanente</strong>. Non è amore. È <strong>controllo psicologico</strong>.</p>","subsections":[]},{"id":"indifferenza-cronica","title":"L''indifferenza cronica","content":"<p>Si parla molto di violenza, manipolazione, gelosia. Ma esiste un''altra forma di <strong>malessere relazionale</strong>, meno spettacolare e altrettanto distruttiva: l''<strong>indifferenza che si installa stabilmente</strong>.</p>\n<p>Un partner che non si interessa più a quello che vivete, che non fa più domande, che non nota più i vostri sforzi, che è <strong>fisicamente presente ma emotivamente assente</strong> — fa danni profondi.</p>\n<p>L''<strong>indifferenza cronica nella coppia</strong> finisce per farvi dubitare del vostro valore. Si inizia a chiedersi se si è abbastanza interessanti, abbastanza amabili. Si cerca di <strong>esistere nello sguardo dell''altro</strong> e non si trova più nulla.</p>\n<p>Certo, tutte le coppie attraversano <strong>fasi di routine</strong>. Il problema è quando l''indifferenza diventa la norma e l''altro non fa <strong>alcuno sforzo per cambiare</strong>. Il nostro <a href=\"https://quiz-couple.com/it/test-relazione-sana\">test di relazione sana</a> può aiutarvi a prendere distanza.</p>","subsections":[]},{"id":"violenza","title":"La violenza — verbale, psicologica, fisica","content":"<p>Bisogna dirlo chiaramente: <strong>nessuna forma di violenza è accettabile</strong> in una relazione. Né la <strong>violenza fisica</strong>, né la <strong>violenza verbale</strong>, né la <strong>violenza psicologica</strong>. Nessuna.</p>\n<p>Eppure, milioni di persone vivono in relazioni dove vengono regolarmente insultate, umiliate, minacciate — e finiscono per credere che sia normale. È il risultato di un <strong>condizionamento progressivo</strong>.</p>\n<p>La <strong>violenza domestica</strong> non arriva da un giorno all''altro. Si installa a tappe: una prima volta che si minimizza, una scusa che si accetta, un <strong>comportamento che si normalizza</strong>.</p>\n<p>Se vivete una situazione di violenza — <strong>meritate di essere al sicuro</strong>. Cercare aiuto non è tradire il partner. È proteggersi.</p>","subsections":[]},{"id":"disprezzo-svalutazione","title":"Il disprezzo e la svalutazione ripetuta","content":"<p>C''è una differenza tra criticare e disprezzare. La critica può essere costruttiva. Il <strong>disprezzo nella coppia</strong> no. Il disprezzo e la <strong>svalutazione ripetuta</strong> attaccano direttamente l''identità dell''altro, il suo valore come persona.</p>\n<p>Sospiri esasperati, <strong>sguardi condiscendenti</strong>, commenti che sottintendono che siete incompetenti o poco intelligenti, <strong>confronti sfavorevoli</strong> con altri — questi comportamenti, identificati dal ricercatore John Gottman come uno dei \"quattro cavalieri dell''Apocalisse\", sono tra i più <strong>predittivi di una rottura</strong> futura.</p>\n<p>Ma prima di portare alla rottura, portano a qualcosa di ancora più grave: la <strong>distruzione dell''autostima</strong>.</p>","subsections":[]},{"id":"tabella-riepilogativa","title":"Tabella riepilogativa: accettare o non accettare?","content":"<table><thead><tr><th>Comportamento</th><th>Da relativizzare se…</th><th>Da non accettare se…</th></tr></thead><tbody>\n<tr><td><strong>Un commento offensivo</strong></td><td>È raro e seguito da scuse sincere</td><td>È ripetuto e minimizzato</td></tr>\n<tr><td><strong>La gelosia</strong></td><td>È leggera e non limitante</td><td>Limita la vostra libertà</td></tr>\n<tr><td><strong>Un conflitto violento</strong></td><td>È eccezionale e affrontato insieme</td><td>Si ripete regolarmente</td></tr>\n<tr><td><strong>La distanza emotiva</strong></td><td>È una fase legata allo stress</td><td>È lo stato permanente della relazione</td></tr>\n<tr><td><strong>Le critiche</strong></td><td>Sono costruttive e benevole</td><td>Mirano a sminuirvi</td></tr>\n</tbody></table>","subsections":[]},{"id":"perche-accettiamo","title":"Perché accettiamo nonostante tutto — e come uscirne","content":"<p>Sapere che non si dovrebbe accettare qualcosa non basta sempre a cambiare le cose. La <strong>paura della solitudine</strong>, l''amore sincero, la difficoltà a immaginare la propria vita diversamente, la <strong>vergogna del giudizio altrui</strong> — tutti questi fattori mantengono persone in <strong>relazioni che fanno loro del male</strong>.</p>\n<p>Non c''è giudizio per chi resta in una situazione difficile. Questi <strong>meccanismi psicologici</strong> sono potenti. Ma c''è qualcosa di importante da capire: <strong>porre dei limiti è possibile</strong>. E porli non significa necessariamente lasciare la relazione.</p>\n<p>Comunicare chiaramente ciò che non si accetta più, dire \"questo comportamento mi ferisce e non posso continuare a subirlo\", è un <strong>atto di rispetto verso sé stessi</strong>.</p>\n<p>Se la persona di fronte a voi non ascolta, minimizza, ricomincia — allora la domanda non è più \"lo/la amo ancora?\" ma \"<strong>mi rispetto abbastanza</strong>\" per fare diversamente? Potete usare il nostro <a href=\"https://quiz-couple.com/it/risolvere-problema-coppia\">risolutore di problemi di coppia</a> per dare parole alla vostra situazione.</p>","subsections":[]},{"id":"porre-limiti","title":"Cosa dice di voi porre dei limiti","content":"<p><strong>Porre dei limiti in una relazione</strong> non è un atto di ostilità. Non è essere \"complicati\", \"esigenti\" o \"difficili da gestire\". Significa semplicemente conoscere il proprio valore e <strong>rifiutare di annullarsi</strong> per compiacere qualcun altro.</p>\n<p>Le <strong>relazioni più solide</strong> sono quelle in cui entrambi i partner sanno dire di no, sanno esprimere i loro disagi, sanno che l''amore non giustifica tutto. Perché il <strong>vero amore</strong> — quello che dura, quello che costruisce — non ha bisogno che vi cancelliate per esistere.</p>\n<p>Avete il diritto di pretendere rispetto, considerazione, onestà. Avete il diritto di sentirvi in <strong>sicurezza emotiva</strong> nella vostra relazione. Il nostro <a href=\"https://quiz-couple.com/it/test-compatibilita-coppia\">test di compatibilità di coppia</a> è un buon punto di partenza per fare il punto.</p>","subsections":[]}]'::jsonb,
    true
  )
